#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> A(N);
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
    }

    sort(A.begin(), A.end());

    long long ans = 0;

    for (int k = 2; k < N; ++k) {
        int i = 0;
        int j = k - 1;

        while (i < j) {
            if (A[i] + A[j] > A[k]) {
                ans += (j - i);
                --j;
            } else {
                ++i;
            }
        }
    }

    cout << ans << '\n';

    return 0;
}
